31	var (
32		localCluster = appv1.Cluster{
33			Name:   "in-cluster",
34			Server: appv1.KubernetesInternalAPIServerAddr,
35			Info: appv1.ClusterInfo{
36				ConnectionState: appv1.ConnectionState{Status: appv1.ConnectionStatusSuccessful},
37			},
38		}
39		initLocalCluster sync.Once
